    parts[3] = getSchool(tokenId);

    parts[4] = '</text><text x="10" y="60" class="base"> Range: ';

    parts[5] = getRange(tokenId);

    parts[6] = '</text><text x="10" y="80" class="base"> Duration: ';

    parts[7] = getDuration(tokenId);

    parts[8] = "</text></svg>";

    string memory output = string(
      abi.encodePacked(
        parts[0],
        parts[1],
        parts[2],
        parts[3],
        parts[4],
        parts[5],
        parts[6],
        parts[7],
        parts[8]
      )
    );

    string memory json = Base64.encode(
      bytes(
        string(
          abi.encodePacked(
            '{"name": "Spell #',
            toString(tokenId),
            '", "description": "Wizard Spells are randomized spells for FRWC wizards generated and stored on chain.", "image": "data:image/svg+xml;base64,',
            Base64.encode(bytes(output)),
            '"}'
          )
        )
      )
    );
    output = string(abi.encodePacked("data:application/json;base64,", json));

